from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # check expiry
            if key in store:
                _, wt = store[key]
                if t >= wt + ttl:
                    del store[key]
            if key in store:
                store[key] = (value, t)
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = (value, t)
                store.move_to_end(key)
        else:
            _, t, key = op
            if key in store:
                value, wt = store[key]
                if t >= wt + ttl:
                    del store[key]
                    results.append(-1)
                else:
                    results.append(value)
                    store.move_to_end(key)
            else:
                results.append(-1)

    return results

